import type { Localized, Lesson, Flashcard, Question, Activity, Lab, ExternalResource } from '../types'; import type { WeekContent } from '../weekContent';
const L=(en:string,es:string,pt:string):Localized=>({en,es,pt}); const X=L; type Ex={title:Localized;prompt:Localized;hint:Localized;solution:Localized;level:1|2|3};
type CheckData=[Localized,Localized,Localized,Localized,Localized,string,Localized,Localized,Localized];
const lesson=(id:string,title:Localized,body:Localized[],analogy:Localized,takeaways:Localized[],c:CheckData,ex:Ex[],code?:{language:string;caption:Localized;source:string}):Lesson=>({id,title,minutes:24,body,analogy,takeaways,check:{question:c[0],options:[c[1],c[2],c[3],c[4]],answer:Number(c[5]),explanation:c[6]},pitfalls:[{mistake:c[7],fix:c[8]}],exercises:ex.map((e,i)=>({id:`${id}-ex${i+1}`,...e})),...(code?{code}:{})});
const card=(id:string,l:string,f:Localized,b:Localized,k:'concept'|'distinction'='concept'):Flashcard=>({id,lessonId:l,front:f,back:b,kind:k});const mc=(id:string,l:string,p:Localized,o:Localized[],a:number,e:Localized):Question=>({id,lessonId:l,type:'multiple-choice',prompt:p,options:o,answer:a,explanation:e});const tf=(id:string,l:string,p:Localized,a:boolean,e:Localized):Question=>({id,lessonId:l,type:'true-false',prompt:p,options:[X('True','Verdadero','Verdadeiro'),X('False','Falso','Falso')],answer:a?0:1,explanation:e});const fill=(id:string,l:string,p:Localized,a:string[],e:Localized):Question=>({id,lessonId:l,type:'fill-blank',prompt:p,accepted:a,explanation:e});const short=(id:string,l:string,p:Localized,a:string[],e:Localized):Question=>({id,lessonId:l,type:'short-answer',prompt:p,accepted:a,explanation:e});const matching=(id:string,l:string,p:Localized,left:Localized[],right:Localized[],answer:number[],e:Localized):Question=>({id,lessonId:l,type:'matching',prompt:p,left,right,answer,explanation:e});const order=(id:string,l:string,t:Localized,p:Localized,items:Localized[],e:Localized):Activity=>({id,lessonId:l,kind:'order',title:t,prompt:p,items,explanation:e});const classify=(id:string,l:string,t:Localized,p:Localized,buckets:Localized[],items:{text:Localized;bucket:number}[],e:Localized):Activity=>({id,lessonId:l,kind:'classify',title:t,prompt:p,buckets,items,explanation:e});const lab=(id:string,t:Localized,g:Localized,steps:{title:Localized;expected:Localized}[]):Lab=>({id,kind:'design',level:2,title:t,goal:g,minutes:35,steps:steps.map((s,i)=>({id:`${id}-s${i+1}`,title:s.title,commands:[],expected:s.expected}))});const res=(id:string,title:string,url:string,n:Localized):ExternalResource=>({id,title,url,kind:'article',verifiedOn:'2026-11-04',note:n});
const lessons:Lesson[]=[
lesson('hist7-l1',X('Cloud and cloud-native systems','Nube y sistemas cloud native','Nuvem e sistemas cloud native'),[
X('Cloud computing offers network access to shared computing resources that can be provisioned and released with limited manual effort. Teams can use infrastructure, platforms, or complete applications as services. This changes software work because capacity, deployment, monitoring, cost, and security cross the boundary between a product team and a provider.','La computación en la nube ofrece acceso por red a recursos compartidos que se asignan y liberan con poca intervención manual. Los equipos usan infraestructura, plataformas o aplicaciones como servicios. Esto cambia despliegue, capacidad, monitoreo, costos y seguridad entre el equipo y el proveedor.','Computação em nuvem oferece acesso pela rede a recursos compartilhados provisionados e liberados com pouca intervenção manual. Equipes usam infraestrutura, plataformas ou aplicações como serviços. Isso muda implantação, capacidade, monitoramento, custo e segurança entre equipe e provedor.'),
X('Cloud-native design generally takes advantage of cloud environments through automation, elastic deployment, and loosely coupled services. Containers and orchestration can help package and operate components, but splitting a program into microservices adds networking, monitoring, deployment, and data-consistency complexity. A well-designed single service may be better than unnecessary distribution.','El diseño cloud native aprovecha entornos en nube mediante automatización, despliegue adaptable y servicios poco acoplados. Contenedores y orquestación ayudan a operar componentes, pero dividir en microservicios agrega complejidad de red, monitoreo, despliegue y datos. Un servicio único bien diseñado puede ser mejor que una distribución innecesaria.','Projeto cloud native aproveita ambientes em nuvem com automação, implantação elástica e serviços pouco acoplados. Contêineres e orquestração podem ajudar a operar componentes, mas dividir em microsserviços acrescenta complexidade de rede, monitoramento, implantação e consistência dos dados. Um serviço único bem projetado pode ser melhor que distribuição desnecessária.')],
X('A modular kitchen can help several cooks work in parallel, but extra stations require more coordination and cleaning.','Una cocina modular permite varios cocineros, pero más estaciones requieren coordinación y limpieza.','Uma cozinha modular permite vários cozinheiros, mas mais estações exigem coordenação e limpeza.'),
[X('Cloud changes operating and commercial responsibilities.','La nube cambia responsabilidades operativas y comerciales.','Nuvem muda responsabilidades operacionais e comerciais.'),X('Microservices add coordination and operational cost.','Los microservicios agregan costos de coordinación y operación.','Microsserviços acrescentam custo de coordenação e operação.')],
[X('What is one tradeoff of splitting a system into microservices?','¿Cuál es una compensación de dividir un sistema en microservicios?','Qual é uma compensação de dividir sistema em microsserviços?'),X('Independent deployment may improve, while network and operations complexity grows.','Puede mejorar despliegue independiente, pero crece complejidad de red y operación.','Implantação independente pode melhorar, mas crescem complexidade de rede e operação.'),X('The system no longer needs monitoring.','El sistema ya no necesita monitoreo.','O sistema não precisa mais de monitoramento.'),X('Data consistency becomes automatic.','La consistencia de datos se vuelve automática.','Consistência dos dados torna-se automática.'),X('Security responsibilities disappear.','Desaparecen las responsabilidades de seguridad.','Responsabilidades de segurança desaparecem.'),'0',X('Distributed components require more operational coordination and explicit communication.','Los componentes distribuidos requieren más coordinación y comunicación explícita.','Componentes distribuídos exigem mais coordenação operacional e comunicação explícita.'),X('Assuming cloud-native always means microservices.','Suponer que cloud native siempre significa microservicios.','Supor que cloud native sempre significa microsserviços.'),X('Choose architecture based on scale, team needs, and operational capability.','Elige arquitectura según escala, equipo y capacidad operativa.','Escolha arquitetura conforme escala, equipe e capacidade operacional.')],
[{title:X('Choose a deployment approach','Elige un enfoque de despliegue','Escolha uma abordagem de implantação'),prompt:X('A small team has one stable application and limited on-call experience. Should it split into many services immediately?','Un equipo pequeño mantiene una aplicación estable y poca experiencia operativa. ¿Debe dividirla enseguida?','Uma equipe pequena tem aplicação estável e pouca experiência de operação. Deve dividi-la imediatamente?'),hint:X('Compare autonomy benefits with distributed-system overhead.','Compara autonomía con costos de sistemas distribuidos.','Compare autonomia com custos de sistemas distribuídos.'),solution:X('Not without a clear need. Start with a maintainable deployment and split only where independent scaling, ownership, or reliability needs justify added operations.','No sin necesidad clara. Empieza con un despliegue mantenible y separa componentes si escalado, propiedad o confiabilidad lo justifican.','Não sem necessidade clara. Comece com implantação sustentável e separe componentes quando escalabilidade, responsabilidade ou confiabilidade justificarem a operação extra.'),level:2},{title:X('Map cloud responsibilities','Mapea responsabilidades de nube','Mapeie responsabilidades da nuvem'),prompt:X('Name one responsibility a customer keeps when using a cloud provider.','Nombra una responsabilidad que conserva el cliente al usar nube.','Cite uma responsabilidade mantida pelo cliente ao usar nuvem.'),hint:X('Think of data, identity, configuration, or workload security.','Piensa en datos, identidad, configuración o seguridad.','Pense em dados, identidade, configuração ou segurança.'),solution:X('The customer still needs to protect identities and data, configure workloads appropriately, monitor service use, and understand shared-responsibility terms.','El cliente protege identidades y datos, configura cargas, monitorea servicios y entiende responsabilidades compartidas.','O cliente protege identidades e dados, configura cargas, monitora serviços e entende responsabilidades compartilhadas.'),level:1}]),
lesson('hist7-l2',X('Artificial intelligence in software','Inteligencia artificial en el software','Inteligência artificial no software'),[
X('AI and machine-learning components can classify, predict, generate, or rank outputs based on data and models. Generative AI can produce text, images, audio, or code, but fluent output is not proof of factual correctness. Performance may vary across users, settings, or input cases, so the system should be evaluated in the context where it will be used.','Los componentes de IA y aprendizaje automático clasifican, predicen, generan u ordenan resultados a partir de datos y modelos. La IA generativa puede producir texto, imágenes, audio o código, pero una respuesta fluida no prueba que sea correcta. El desempeño varía según usuarios, contexto o entradas; hay que evaluarlo para el uso previsto.','Componentes de IA e aprendizado de máquina classificam, predizem, geram ou ordenam resultados com base em dados e modelos. IA generativa pode produzir texto, imagens, áudio ou código, mas fluência não prova correção factual. O desempenho pode variar por usuário, contexto ou entrada; avalie para o uso previsto.'),
X('Responsible AI engineering includes choosing an appropriate use, checking data and model limitations, measuring performance and bias, protecting privacy, documenting uncertainty, and monitoring after release. Human review can help in high-impact contexts, but it must be meaningful: reviewers need time, authority, and enough information to challenge an output.','La ingeniería responsable de IA elige usos apropiados, revisa datos y límites del modelo, mide desempeño y sesgos, protege privacidad, documenta incertidumbre y monitorea tras el lanzamiento. La revisión humana puede ayudar en usos de alto impacto, pero debe ser real: revisores necesitan tiempo, autoridad e información para cuestionar resultados.','Engenharia responsável de IA escolhe usos apropriados, verifica dados e limitações, mede desempenho e viés, protege privacidade, documenta incerteza e monitora após lançamento. Revisão humana ajuda em contextos de alto impacto, mas precisa ser efetiva: revisores precisam de tempo, autoridade e informação para contestar resultados.')],
X('A calculator can produce a precise-looking answer to the wrong equation; inspect the problem and result, not just the display.','Una calculadora puede mostrar una respuesta precisa para la ecuación equivocada; revisa problema y resultado.','Uma calculadora pode mostrar resposta precisa para equação errada; confira problema e resultado, não só a tela.'),
[X('AI outputs need context-specific evaluation.','Los resultados de IA requieren evaluación contextual.','Resultados de IA exigem avaliação contextual.'),X('Trustworthiness includes privacy, validity, reliability, fairness, and accountability.','La confiabilidad incluye privacidad, validez, equidad y responsabilidad.','Confiabilidade inclui privacidade, validade, equidade e responsabilização.')],
[X('A generated answer sounds confident. What should a team do before relying on it?','Una respuesta generada parece segura. ¿Qué debería hacer el equipo antes de confiar?','Uma resposta gerada parece confiante. O que a equipe deve fazer antes de confiar?'),X('Evaluate it against representative cases and verify important claims.','Evaluarla con casos representativos y verificar afirmaciones importantes.','Avaliar com casos representativos e verificar afirmações importantes.'),X('Assume fluency means accuracy.','Suponer que la fluidez significa exactitud.','Supor que fluência significa precisão.'),X('Skip monitoring.','Omitir monitoreo.','Pular monitoramento.'),X('Use it in every workflow.','Usarla en todo flujo.','Usá-la em todo fluxo.'),'0',X('Fluency does not establish factual accuracy, safety, or suitability.','La fluidez no demuestra exactitud, seguridad ni idoneidad.','Fluência não prova precisão, segurança ou adequação.'),X('Treating a human-in-the-loop label as sufficient oversight.','Pensar que “revisión humana” basta por sí sola.','Supor que rótulo “humano no circuito” basta.'),X('Give reviewers evidence, time, authority, and a way to override.','Da evidencia, tiempo, autoridad y opción de anular.','Ofereça evidências, tempo, autoridade e opção de substituir a saída.')],
[{title:X('Assess an AI use case','Evalúa un caso de IA','Avalie um caso de IA'),prompt:X('A clinic considers using AI to draft appointment summaries. Name two safeguards.','Una clínica considera usar IA para redactar resúmenes de citas. Nombra dos salvaguardas.','Uma clínica considera IA para rascunhar resumos de consultas. Cite duas salvaguardas.'),hint:X('Think about sensitive data and human review.','Piensa en datos sensibles y revisión humana.','Pense em dados sensíveis e revisão humana.'),solution:X('Protect health data, evaluate outputs on representative cases, show uncertainty, require meaningful clinician review, and monitor errors.','Proteger datos de salud, evaluar casos, mostrar incertidumbre, exigir revisión clínica y monitorear errores.','Proteja dados de saúde, avalie casos representativos, mostre incerteza, exija revisão clínica efetiva e monitore erros.'),level:3},{title:X('Separate capability from guarantee','Distingue capacidad y garantía','Diferencie capacidade e garantia'),prompt:X('An AI tool can summarize reports. Does that guarantee it catches every critical fact? Explain.','Una herramienta resume informes. ¿Garantiza captar cada dato crítico? Explica.','Uma ferramenta resume relatórios. Isso garante que detecte todo fato crítico? Explique.'),hint:X('Capabilities are not guarantees.','Las capacidades no son garantías.','Capacidades não são garantias.'),solution:X('No. It may omit or distort details; test it, compare against the source, and keep accountable review for critical use.','No. Puede omitir o alterar detalles; pruébala, compárala con la fuente y mantén revisión responsable.','Não. Pode omitir ou distorcer detalhes; teste, compare com a fonte e mantenha revisão responsável.'),level:2}]),
lesson('hist7-l3',X('Blockchain and smart contracts','Blockchain y contratos inteligentes','Blockchain e contratos inteligentes'),[
X('A blockchain is a replicated ledger maintained by a network of participants under shared rules. Transactions update shared state, and consensus mechanisms determine which updates are accepted. A smart contract is code deployed on a blockchain that responds to transactions according to its programmed rules.','Una blockchain es un registro replicado que mantiene una red bajo reglas compartidas. Las transacciones actualizan un estado común y mecanismos de consenso determinan qué cambios se aceptan. Un contrato inteligente es código desplegado en una blockchain que responde a transacciones según reglas programadas.','Uma blockchain é um registro replicado mantido por uma rede sob regras compartilhadas. Transações atualizam estado comum e mecanismos de consenso determinam quais mudanças são aceitas. Um contrato inteligente é código implantado em blockchain que responde a transações segundo regras programadas.'),
X('Smart contracts can automate shared rules, but they cannot automatically know facts in the outside world without an external data source. Bugs or design errors can be costly because some deployed code is difficult to change and some actions cannot be reversed. Engineers must ask whether a shared ledger solves a real coordination problem better than a conventional database.','Contratos inteligentes automatizan reglas compartidas, pero no conocen hechos externos sin una fuente de datos. Errores pueden costar caro porque cierto código desplegado es difícil de cambiar y algunas acciones no se revierten. Hay que evaluar si un registro compartido resuelve mejor una necesidad que una base de datos convencional.','Smart contracts podem automatizar regras compartilhadas, mas não conhecem fatos externos sem fonte de dados. Erros podem custar caro porque código implantado pode ser difícil de mudar e algumas ações são irreversíveis. Engenheiros devem avaliar se registro compartilhado resolve melhor um problema real que banco de dados convencional.')],
X('A shared logbook can make edits visible to several parties, but someone still must verify that each entry describes a real event.','Un registro compartido hace visibles los cambios para varias partes, pero alguien debe verificar que cada dato refleje un hecho real.','Um registro compartilhado torna alterações visíveis a várias partes, mas alguém ainda precisa verificar se cada registro descreve fato real.'),
[X('Smart contracts execute coded rules on a blockchain.','Los contratos inteligentes ejecutan reglas codificadas en blockchain.','Smart contracts executam regras codificadas em blockchain.'),X('A ledger does not automatically verify off-chain facts.','Un registro no verifica automáticamente hechos externos.','Um ledger não verifica automaticamente fatos externos.')],
[X('A smart contract needs the temperature of a real shipment. What is a limitation to address?','Un contrato necesita la temperatura real de un envío. ¿Qué limitación debe atender?','Um contrato precisa da temperatura real de uma carga. Que limitação deve ser considerada?'),X('It needs a trusted way to obtain off-chain sensor data.','Necesita una fuente confiable para datos externos del sensor.','Precisa de forma confiável de obter dados externos do sensor.'),X('The blockchain senses temperature by itself.','La blockchain mide temperatura por sí sola.','A blockchain mede temperatura sozinha.'),X('It must avoid all transactions.','Debe evitar transacciones.','Deve evitar transações.'),X('The code replaces the physical sensor.','El código reemplaza el sensor físico.','O código substitui o sensor físico.'),'0',X('A blockchain cannot observe outside facts without an oracle or another data mechanism.','La blockchain no observa hechos externos sin oráculo u otro mecanismo.','Blockchain não observa fatos externos sem oráculo ou outro mecanismo de dados.'),X('Assuming decentralization removes trust from every input.','Suponer que descentralizar elimina la confianza de toda entrada.','Supor que descentralização elimina confiança em toda entrada.'),X('Identify who supplies data and how it is validated and disputed.','Identifica quién entrega datos y cómo se validan o cuestionan.','Identifique quem fornece dados e como são validados ou contestados.')],
[{title:X('Compare ledger and database','Compara registro y base de datos','Compare ledger e banco de dados'),prompt:X('Three independent organizations need to update a shared record, but none wants one party to control it. What blockchain benefit may matter?','Tres organizaciones comparten registros y ninguna quiere que una controle todo. ¿Qué posible ventaja importa?','Três organizações atualizam registro compartilhado e nenhuma quer controle unilateral. Que benefício possível importa?'),hint:X('Focus on shared control and replicated history.','Enfócate en control compartido e historial replicado.','Concentre-se em controle compartilhado e histórico replicado.'),solution:X('A shared replicated ledger may help when participants need a common history without relying on one operator, but compare governance, performance, privacy, and costs.','Un registro replicado puede ayudar sin operador único, pero compara gobierno, rendimiento, privacidad y costos.','Um ledger replicado pode ajudar sem operador único, mas compare governança, desempenho, privacidade e custos.'),level:2},{title:X('Identify the oracle problem','Identifica el problema del oráculo','Identifique o problema do oráculo'),prompt:X('Why does smart-contract code need an oracle to react to a flight cancellation?','¿Por qué el contrato necesita un oráculo para reaccionar a una cancelación de vuelo?','Por que o contrato precisa de oráculo para reagir a cancelamento de voo?'),hint:X('The blockchain cannot observe airline operations directly.','La blockchain no observa directamente operaciones aéreas.','A blockchain não observa operações aéreas diretamente.'),solution:X('Flight status exists outside the ledger, so an external source must report it; the design must assess that source’s integrity and availability.','El estado del vuelo está fuera del registro; una fuente externa debe informarlo y se debe evaluar su integridad.','Status do voo está fora do ledger; fonte externa deve informá-lo e sua integridade precisa ser avaliada.'),level:2}]),
lesson('hist7-l4',X('Low-code, no-code, and immersive interfaces','Low-code, no-code e interfaces imersivas','Low-code, no-code e interfaces imersivas'),[
X('Low-code and no-code platforms use visual builders, reusable components, and declarative configuration to speed up common applications or workflows. They can let domain experts contribute directly, while professional developers extend integrations and controls. The tradeoffs include platform lock-in, customization limits, governance gaps, and hidden complexity.','Las plataformas low-code y no-code usan editores visuales, componentes reutilizables y configuración declarativa para crear aplicaciones o flujos comunes. Permiten participar a especialistas del dominio y a desarrolladores ampliar integraciones. Sus compensaciones incluyen dependencia, límites de personalización, gobierno y complejidad oculta.','Plataformas low-code e no-code usam construtores visuais, componentes reutilizáveis e configuração declarativa para acelerar aplicações e fluxos comuns. Especialistas do domínio podem participar e desenvolvedores ampliam integrações. Compensações incluem dependência da plataforma, limites de personalização, lacunas de governança e complexidade oculta.'),
X('Immersive or “metaverse” experiences combine software, networks, and devices to create shared 3D spaces. The label has been used for different products, so evaluate a concrete use rather than relying on hype. Ask whether immersion improves the task enough to justify device cost, accessibility needs, privacy, safety, and user comfort.','Las experiencias inmersivas o “metaverso” combinan software, redes y dispositivos para crear espacios 3D compartidos. El término cubre productos distintos; evalúa un uso concreto, no la publicidad. Pregunta si la inmersión mejora una tarea lo suficiente para justificar costos, accesibilidad, privacidad, seguridad y comodidad.','Experiências imersivas ou “metaverso” combinam software, redes e dispositivos para criar espaços 3D compartilhados. O termo abrange produtos diferentes; avalie um uso concreto, não a propaganda. Pergunte se imersão melhora a tarefa o suficiente para justificar custo, acessibilidade, privacidade, segurança e conforto.')],
X('A template kit helps someone assemble a familiar room quickly, but unusual requirements may exceed the kit’s boundaries.','Una plantilla permite montar rápido un espacio conocido, pero requisitos inusuales pueden superar sus límites.','Um kit de modelos permite montar espaço familiar rapidamente, mas requisitos incomuns podem exceder seus limites.'),
[X('Low-code lowers effort for common tasks but still needs governance.','Low-code reduce esfuerzo en tareas comunes, pero necesita gobierno.','Low-code reduz esforço em tarefas comuns, mas ainda exige governança.'),X('Immersive technology should be judged by a specific user task.','La tecnología inmersiva debe evaluarse según una tarea de usuario concreta.','Tecnologia imersiva deve ser avaliada por tarefa específica do usuário.')],
[X('What is a sensible low-code governance concern?','¿Qué preocupación de gobierno low-code es sensata?','Qual preocupação de governança low-code é sensata?'),X('Who can access the data and how will changes be maintained?','¿Quién accede a los datos y cómo se mantendrán los cambios?','Quem acessa os dados e como mudanças serão mantidas?'),X('Visual tools eliminate security risk.','Las herramientas visuales eliminan riesgos de seguridad.','Ferramentas visuais eliminam riscos de segurança.'),X('No documentation is needed.','No hace falta documentación.','Não é necessária documentação.'),X('Every workflow can be customized without limits.','Todo flujo se personaliza sin límites.','Todo fluxo pode ser personalizado sem limites.'),'0',X('Visual development still creates applications, integrations, identities, and data that need governance.','El desarrollo visual sigue creando aplicaciones, integraciones, identidades y datos que requieren gobierno.','Desenvolvimento visual ainda cria aplicações, integrações, identidades e dados que exigem governança.'),X('Assuming less code means no technical responsibility.','Suponer que menos código significa menos responsabilidad técnica.','Supor que menos código significa ausência de responsabilidade técnica.'),X('Review security, ownership, integration, portability, and maintenance.','Revisa seguridad, propiedad, integración, portabilidad y mantenimiento.','Revise segurança, propriedade, integração, portabilidade e manutenção.')],
[{title:X('Assess a low-code workflow','Evalúa un flujo low-code','Avalie um fluxo low-code'),prompt:X('A department wants to create a form that stores employee health data. Name two controls before launch.','Un departamento crea un formulario con datos de salud de empleados. Nombra dos controles.','Um departamento quer criar formulário com dados de saúde de funcionários. Cite dois controles.'),hint:X('Sensitive data needs strict purpose and access controls.','Los datos sensibles requieren propósito y controles de acceso.','Dados sensíveis exigem finalidade clara e controles de acesso.'),solution:X('Check necessity and consent/legal basis, limit access, retention, audit logs, platform security, and a tested deletion process.','Revisa necesidad, base legal, acceso limitado, retención, auditoría, seguridad y borrado.','Verifique necessidade, base legal, acesso, retenção, auditoria, segurança da plataforma e exclusão testada.'),level:3},{title:X('Test an immersive idea','Prueba una idea inmersiva','Teste uma ideia imersiva'),prompt:X('What is one way to decide whether a 3D training space is useful?','¿Cómo decidir si sirve un espacio 3D de capacitación?','Como decidir se espaço 3D de treinamento é útil?'),hint:X('Compare learning outcomes with cost and access.','Compara resultados de aprendizaje con costo y acceso.','Compare resultados de aprendizagem com custo e acesso.'),solution:X('Run a limited trial with accessible alternatives; measure task learning, safety, comfort, device access, and operating cost against a simpler format.','Prueba limitada y accesible; mide aprendizaje, seguridad, comodidad, acceso y costos frente a un formato simple.','Faça teste limitado com alternativa acessível; meça aprendizagem, segurança, conforto, acesso e custo frente a formato simples.'),level:2}]),
lesson('hist7-l5',X('Evaluate a trend without hype','Evalúa una tendencia sin exageración','Avalie tendência sem exagero'),[
X('A technology trend becomes meaningful when it responds to a real need and works within practical, ethical, and economic constraints. A prototype can show technical possibility; a pilot can test usability and operations; wider evidence is needed to establish value, reliability, and impact. Distinguish a demo, a product, and a proven outcome.','Una tendencia importa si responde a una necesidad y funciona bajo restricciones prácticas, éticas y económicas. Un prototipo muestra posibilidad técnica; un piloto prueba uso y operación; hacen falta más evidencias para validar valor e impacto. Distingue demostración, producto y resultado comprobado.','Uma tendência importa quando atende necessidade real e funciona sob restrições práticas, éticas e econômicas. Protótipo mostra possibilidade técnica; piloto testa uso e operação; mais evidências são necessárias para valor e impacto. Diferencie demonstração, produto e resultado comprovado.'),
X('A balanced review considers users, performance, security, privacy, accessibility, cost, environmental or social effects, and what happens when the system fails. It asks what evidence supports a claim, who benefits, who bears risk, and whether a simpler alternative meets the goal. Historical perspective helps recognize repeated promises and recurring engineering tradeoffs.','Una revisión equilibrada considera usuarios, rendimiento, seguridad, privacidad, accesibilidad, costos, efectos sociales y fallos. Pregunta qué evidencia respalda una afirmación, quién se beneficia, quién asume riesgos y si una alternativa simple cumple la meta. La historia ayuda a reconocer promesas y compensaciones recurrentes.','Uma revisão equilibrada considera usuários, desempenho, segurança, privacidade, acessibilidade, custo, efeitos sociais e falhas. Pergunta que evidências apoiam uma alegação, quem se beneficia, quem assume riscos e se alternativa simples atende à meta. História ajuda a reconhecer promessas e compensações recorrentes.')],
X('A test kitchen distinguishes a recipe video from food that tastes good, can be made safely, and works at scale.','Una cocina de prueba distingue el video de una receta del alimento que sabe bien, es seguro y funciona en escala.','Uma cozinha de testes diferencia vídeo de receita de comida saborosa, segura e viável em escala.'),
[X('Separate capability, product readiness, and proven value.','Distingue capacidad, madurez de producto y valor demostrado.','Diferencie capacidade, prontidão do produto e valor comprovado.'),X('Evaluate risks and alternatives alongside benefits.','Evalúa riesgos y alternativas junto con beneficios.','Avalie riscos e alternativas junto aos benefícios.')],
[X('A vendor reports a successful demo. What does that prove?','Un proveedor presenta una demostración exitosa. ¿Qué demuestra?','Um fornecedor apresenta demonstração bem-sucedida. O que isso prova?'),X('That a capability worked in that demo; not that it is reliable or valuable at scale.','Que una capacidad funcionó allí; no que sea confiable o valiosa a escala.','Que uma capacidade funcionou naquela demonstração; não que seja confiável ou valiosa em escala.'),X('That every user will benefit.','Que toda persona se beneficiará.','Que todo usuário se beneficiará.'),X('That costs are negligible.','Que los costos son mínimos.','Que os custos são insignificantes.'),X('That no evaluation is needed.','Que no hace falta evaluar.','Que nenhuma avaliação é necessária.'),'0',X('A demonstration is limited evidence and does not establish field performance or impact.','Una demostración es evidencia limitada y no establece desempeño o impacto real.','Uma demonstração é evidência limitada e não estabelece desempenho ou impacto em campo.'),X('Treating predictions or marketing claims as results.','Tratar predicciones o publicidad como resultados.','Tratar previsões ou marketing como resultados.'),X('Ask for representative evaluation, user outcomes, failure data, and operating cost.','Solicita evaluación representativa, resultados, fallos y costos.','Solicite avaliação representativa, resultados, dados de falha e custo operacional.')],
[{title:X('Build an evidence ladder','Construye una escala de evidencia','Monte uma escala de evidências'),prompt:X('What evidence would you want before relying on an AI assistant for a high-impact decision?','¿Qué evidencia pedirías antes de confiar en IA para una decisión de alto impacto?','Que evidências pediria antes de confiar em assistente de IA para decisão de alto impacto?'),hint:X('Move from lab demo to representative use and monitoring.','Pasa de demostración a uso representativo y monitoreo.','Avance de demonstração a uso representativo e monitoramento.'),solution:X('Use representative validation data, known limitations, subgroup performance, privacy and security review, human oversight design, incident handling, and post-deployment monitoring.','Pide validación representativa, límites, resultados por grupos, privacidad, seguridad, supervisión humana y monitoreo.','Exija validação representativa, limitações, desempenho por grupos, privacidade, segurança, supervisão humana e monitoramento.'),level:3},{title:X('Compare with a simpler option','Compara con una opción sencilla','Compare com opção mais simples'),prompt:X('Why compare an emerging tool with a non-AI or non-blockchain alternative?','¿Por qué comparar una herramienta nueva con una alternativa sin IA o blockchain?','Por que comparar ferramenta emergente a alternativa sem IA ou blockchain?'),hint:X('Compare problem fit, cost, reliability, and complexity.','Compara adecuación, costo, confiabilidad y complejidad.','Compare adequação, custo, confiabilidade e complexidade.'),solution:X('A simpler system may meet the need with lower cost, fewer new risks, and easier maintenance; comparison reveals whether the new tool adds enough value.','Una opción simple puede cubrir la necesidad con menos costo, riesgo y mantenimiento; la comparación muestra el valor adicional.','Sistema simples pode atender necessidade com menor custo, risco e manutenção; comparação revela se nova ferramenta agrega valor suficiente.'),level:2}],{language:'text',caption:X('A practical technology review','Revisión práctica de tecnología','Avaliação prática de tecnologia'),source:'Need → Feasibility → Prototype → Representative evaluation → Risk review → Operate and monitor'})
];
const cards:Flashcard[]=[
card('h7-c1','hist7-l1',X('What characterizes cloud computing?','¿Qué caracteriza la computación en nube?','O que caracteriza computação em nuvem?'),X('Network access to shared, configurable resources that can be provisioned on demand.','Acceso por red a recursos compartidos configurables bajo demanda.','Acesso pela rede a recursos compartilhados e configuráveis sob demanda.')),
card('h7-c2','hist7-l1',X('Cloud-native architecture','Arquitectura cloud native','Arquitetura cloud native'),X('Uses cloud capabilities and automation; it does not automatically require microservices.','Aprovecha capacidades de nube y automatización; no exige microservicios.','Usa recursos de nuvem e automação; não exige microsserviços.'),'distinction'),
card('h7-c3','hist7-l1',X('Name one microservice tradeoff.','Nombra una compensación de microservicios.','Cite uma compensação de microsserviços.'),X('More independent deployment can mean more network, monitoring, and operations complexity.','Despliegue independiente agrega complejidad de red, monitoreo y operación.','Implantação independente pode trazer complexidade de rede, monitoramento e operação.')),
card('h7-c4','hist7-l2',X('What does generative AI do?','¿Qué hace la IA generativa?','O que IA generativa faz?'),X('Generates outputs such as text, images, audio, or code from a model.','Genera texto, imágenes, audio o código a partir de un modelo.','Gera texto, imagens, áudio ou código a partir de um modelo.')),
card('h7-c5','hist7-l2',X('Does fluent output prove accuracy?','¿La fluidez prueba exactitud?','Fluência prova precisão?'),X('No. Important outputs require context-specific evaluation and verification.','No. Los resultados importantes requieren evaluación y verificación.','Não. Resultados importantes exigem avaliação contextual e verificação.'),'distinction'),
card('h7-c6','hist7-l2',X('What makes human review meaningful?','¿Qué hace útil la revisión humana?','O que torna revisão humana efetiva?'),X('Reviewer has information, time, expertise, authority, and an override path.','La persona revisora tiene información, tiempo, experiencia, autoridad y opción de anular.','Revisor tem informação, tempo, experiência, autoridade e opção de substituição.')),
card('h7-c7','hist7-l3',X('What is a smart contract?','¿Qué es un contrato inteligente?','O que é smart contract?'),X('Code on a blockchain that executes rules in response to transactions.','Código en blockchain que ejecuta reglas ante transacciones.','Código em blockchain que executa regras em resposta a transações.')),
card('h7-c8','hist7-l3',X('What is the oracle problem?','¿Qué es el problema del oráculo?','O que é o problema do oráculo?'),X('A blockchain cannot directly know outside-world facts without an external data source.','La blockchain necesita datos externos para conocer hechos del mundo real.','Blockchain precisa de fonte externa para conhecer fatos do mundo real.')),
card('h7-c9','hist7-l4',X('What is low-code?','¿Qué es low-code?','O que é low-code?'),X('Visual builders and reusable components reduce manual coding for common tasks.','Constructores visuales y componentes reducen código manual en tareas comunes.','Construtores visuais e componentes reduzem programação manual em tarefas comuns.')),
card('h7-c10','hist7-l4',X('Name a low-code risk.','Nombra un riesgo low-code.','Cite risco low-code.'),X('Platform dependence, access-control gaps, limited customization, or weak governance.','Dependencia, controles de acceso débiles, personalización limitada o gobierno deficiente.','Dependência da plataforma, controle fraco, personalização limitada ou governança inadequada.')),
card('h7-c11','hist7-l5',X('What does a demo establish?','¿Qué demuestra una demostración?','O que uma demonstração comprova?'),X('A capability worked in one setting; not readiness, broad reliability, or impact.','Una capacidad funcionó en un caso; no madurez, confiabilidad amplia o impacto.','Uma capacidade funcionou em um caso; não prontidão, confiabilidade ampla ou impacto.')),
card('h7-c12','hist7-l5',X('Why compare a simpler alternative?','¿Por qué comparar una alternativa sencilla?','Por que comparar alternativa simples?'),X('It reveals whether a new technology adds enough value to justify cost and risk.','Revela si la nueva tecnología aporta valor suficiente para su costo y riesgo.','Revela se nova tecnologia agrega valor suficiente para justificar custo e risco.'))
];
const questions:Question[]=[
mc('h7-q1','hist7-l1',X('Which is a cloud-native design consideration?','¿Cuál es una consideración cloud native?','Qual é uma consideração cloud native?'),[X('Automation and operation of services across a cloud environment.','Automatización y operación de servicios en nube.','Automação e operação de serviços em ambiente de nuvem.'),X('Using microservices in every case.','Usar microservicios siempre.','Usar microsserviços em todos os casos.'),X('Removing monitoring.','Eliminar monitoreo.','Remover monitoramento.'),X('Assuming provider outages cannot happen.','Suponer que no habrá fallos del proveedor.','Supor que provedor nunca falhará.')],0,X('Cloud-native work takes advantage of cloud capabilities while still requiring operational design.','Cloud native aprovecha nube y requiere diseño operativo.','Cloud native aproveita nuvem e exige projeto operacional.')),
tf('h7-q2','hist7-l1',X('Cloud-native automatically means microservices.','Cloud native siempre significa microservicios.','Cloud native sempre significa microsserviços.'),false,X('A system can use cloud-native practices without decomposing into many services.','Puede aprovechar nube sin dividirse en muchos servicios.','Pode aproveitar nuvem sem ser dividido em muitos serviços.')),
mc('h7-q3','hist7-l2',X('What is a key AI system risk to measure?','¿Qué riesgo clave debe medirse en IA?','Que risco importante deve ser medido em IA?'),[X('Validity and performance in the intended use context.','Validez y desempeño en el uso previsto.','Validade e desempenho no contexto pretendido.'),X('Whether output sounds confident.','Si la respuesta suena confiada.','Se a saída parece confiante.'),X('How colorful the interface is.','Qué colorida es la interfaz.','Quão colorida é a interface.'),X('The number of prompts only.','Solo la cantidad de solicitudes.','Apenas número de solicitações.')],0,X('Evaluation should reflect users, conditions, and risks of the actual use.','La evaluación debe reflejar usuarios, condiciones y riesgos reales.','Avaliação deve refletir usuários, condições e riscos do uso real.')),
fill('h7-q4','hist7-l2',X('The NIST AI RMF 1.0 was published in ______.','NIST publicó AI RMF 1.0 en ______.','NIST publicou AI RMF 1.0 em ______.'),['2023'],X('NIST released its AI Risk Management Framework 1.0 in 2023.','NIST publicó su Marco de Gestión de Riesgos de IA en 2023.','NIST lançou seu Framework de Gestão de Risco de IA em 2023.')),
mc('h7-q5','hist7-l3',X('What limitation affects smart contracts?','¿Qué límite afecta los contratos inteligentes?','Que limitação afeta smart contracts?'),[X('They need external data mechanisms for off-chain facts.','Necesitan mecanismos externos para hechos fuera de la cadena.','Precisam de mecanismos externos para fatos fora da cadeia.'),X('They cannot store program state.','No pueden guardar estado.','Não podem armazenar estado.'),X('They are ordinary paper agreements.','Son acuerdos en papel.','São acordos em papel.'),X('They always reverse transactions.','Siempre revierten transacciones.','Sempre revertem transações.')],0,X('Blockchains do not observe external events by themselves.','Las blockchains no observan eventos externos por sí solas.','Blockchains não observam eventos externos sozinhas.')),
tf('h7-q6','hist7-l3',X('A smart contract can make code-based transactions difficult to reverse.','Un contrato inteligente puede hacer difícil revertir transacciones codificadas.','Um smart contract pode tornar difícil reverter transações codificadas.'),true,X('Some blockchain interactions are irreversible or difficult to change, so defects need careful handling.','Algunas interacciones son irreversibles o difíciles de cambiar; se requieren controles.','Algumas interações são irreversíveis ou difíceis de mudar; defeitos exigem cuidado.')),
matching('h7-q7','hist7-l4',X('Match the trend with a design question.','Relaciona la tendencia con una pregunta de diseño.','Associe a tendência à pergunta de projeto.'),[X('Low-code','Low-code','Low-code'),X('AI model','Modelo de IA','Modelo de IA'),X('Immersive interface','Interfaz inmersiva','Interface imersiva')],[X('Who controls data and platform changes?','¿Quién controla datos y cambios de plataforma?','Quem controla dados e mudanças da plataforma?'),X('How is performance and bias evaluated?','¿Cómo se evalúan desempeño y sesgo?','Como desempenho e viés são avaliados?'),X('Does immersion improve the user task accessibly?','¿La inmersión mejora la tarea con accesibilidad?','Imersão melhora tarefa de modo acessível?')],[0,1,2],X('Different trends raise distinct user, operational, and governance questions.','Cada tendencia plantea preguntas distintas de uso y gobierno.','Cada tendência levanta questões distintas de uso e governança.')),
tf('h7-q8','hist7-l5',X('A successful pilot proves the system works for all users at all scales.','Un piloto exitoso prueba que el sistema funciona para todos y a cualquier escala.','Um piloto bem-sucedido prova que sistema funciona para todos e em qualquer escala.'),false,X('A pilot is limited evidence; broader evaluation is needed for wider claims.','Un piloto es evidencia limitada; hacen falta evaluaciones más amplias.','Um piloto é evidência limitada; afirmações amplas exigem mais avaliação.')),
short('h7-q9','hist7-l5',X('Name one factor beyond technical feasibility in evaluating a trend.','Nombra un factor además de viabilidad técnica.','Cite um fator além de viabilidade técnica.'),['privacy|privacidad|privacidade','cost|costo|custo','accessibility|accesibilidad|acessibilidade','security|seguridad|segurança','impact|impacto|impacto','reliability|confiabilidad|confiabilidade'],X('Consider users, privacy, security, accessibility, cost, reliability, and impact.','Considera usuarios, privacidad, seguridad, accesibilidad, costos e impacto.','Considere usuários, privacidade, segurança, acessibilidade, custo e impacto.')),
mc('h7-q10','hist7-l5',X('Why compare a new technology with a simpler solution?','¿Por qué comparar una tecnología nueva con una solución simple?','Por que comparar tecnologia nova a solução simples?'),[X('To test whether added benefits justify cost, complexity, and risk.','Para evaluar si beneficios justifican costo, complejidad y riesgo.','Para avaliar se benefícios justificam custo, complexidade e risco.'),X('To avoid measuring outcomes.','Para evitar medir resultados.','Para evitar medir resultados.'),X('To prefer novelty automatically.','Para preferir siempre lo novedoso.','Para sempre preferir novidade.'),X('To ignore the user task.','Para ignorar la tarea del usuario.','Para ignorar a tarefa do usuário.')],0,X('A baseline comparison helps establish whether a trend solves the problem better.','La comparación permite comprobar si la tendencia resuelve mejor el problema.','Comparação ajuda a verificar se tendência resolve melhor o problema.'))
];
const activities:Activity[]=[
order('h7-a1','hist7-l1',X('From local deployment to managed cloud','De despliegue local a nube gestionada','De implantação local à nuvem gerenciada'),X('Arrange these broad deployment changes in order.','Ordena estos cambios amplios de despliegue.','Organize estas mudanças amplas de implantação.'),[X('Software runs on an organization-owned server','Software corre en servidor propio','Software roda em servidor da organização'),X('Virtualized resources can be provisioned on demand','Recursos virtualizados se asignan bajo demanda','Recursos virtualizados são provisionados sob demanda'),X('Managed applications are delivered as services','Aplicaciones gestionadas se ofrecen como servicios','Aplicações gerenciadas são entregues como serviços')],X('The sequence represents an expanding use of shared and managed resources, not a universal replacement history.','La secuencia muestra uso creciente de recursos compartidos, no reemplazo universal.','A sequência mostra uso crescente de recursos compartilhados, não substituição universal.')),
classify('h7-a2','hist7-l2',X('Match the risk area','Relaciona el área de riesgo','Associe a área de risco'),X('Place each concern in the closest review area.','Ubica cada preocupación en el área de revisión más cercana.','Coloque cada preocupação na área de revisão mais próxima.'),[X('AI evaluation','Evaluación de IA','Avaliação de IA'),X('Cloud operation','Operación de nube','Operação da nuvem'),X('Blockchain design','Diseño blockchain','Projeto blockchain')],[{text:X('Subgroup performance and output validity','Desempeño por grupos y validez','Desempenho por grupo e validade'),bucket:0},{text:X('Availability and exit strategy','Disponibilidad y estrategia de salida','Disponibilidade e estratégia de saída'),bucket:1},{text:X('External data source integrity','Integridad de fuente externa','Integridade da fonte externa'),bucket:2},{text:X('Provider access controls','Controles de acceso del proveedor','Controles de acesso do provedor'),bucket:1}],X('Each technology introduces distinct failure and governance questions.','Cada tecnología plantea riesgos y preguntas de gobierno distintos.','Cada tecnologia traz riscos e questões de governança próprios.')),
order('h7-a3','hist7-l5',X('Evaluate a technology proposal','Evalúa una propuesta tecnológica','Avalie uma proposta tecnológica'),X('Arrange a responsible path from need to operation.','Ordena un camino responsable desde la necesidad a la operación.','Organize um caminho responsável da necessidade à operação.'),[X('State a concrete user need','Definir una necesidad concreta','Definir necessidade concreta'),X('Compare simpler alternatives','Comparar alternativas sencillas','Comparar alternativas simples'),X('Prototype and test with representative cases','Crear prototipo y probar casos representativos','Prototipar e testar casos representativos'),X('Review risk, cost, accessibility, and monitoring','Revisar riesgo, costo, acceso y monitoreo','Revisar risco, custo, acessibilidade e monitoramento')],X('Start with the task, gather evidence, and plan ongoing safeguards.','Empieza con la tarea, reúne evidencia y planifica salvaguardas.','Comece pela tarefa, reúna evidências e planeje salvaguardas.')),
classify('h7-a4','hist7-l4',X('Technology and tradeoffs','Tecnología y compensaciones','Tecnologia e compensações'),X('Sort each statement to the trend it most directly describes.','Clasifica cada afirmación bajo la tendencia correspondiente.','Classifique cada afirmação na tendência correspondente.'),[X('Generative AI','IA generativa','IA generativa'),X('Low-code','Low-code','Low-code'),X('Blockchain','Blockchain','Blockchain'),X('Immersive systems','Sistemas inmersivos','Sistemas imersivos')],[{text:X('Fluent output can still be inaccurate','La fluidez no prueba exactitud','Fluência não prova precisão'),bucket:0},{text:X('Visual builders may limit portability','Los editores pueden limitar portabilidad','Construtores visuais podem limitar portabilidade'),bucket:1},{text:X('External facts need a trusted data path','Hechos externos requieren fuente confiable','Fatos externos exigem fonte confiável'),bucket:2},{text:X('Device comfort and accessibility matter','Comodidad y accesibilidad de dispositivos','Conforto e acessibilidade dos dispositivos importam'),bucket:3}],X('Each trend has a distinct engineering and user experience risk.','Cada tendencia tiene riesgos técnicos y de uso propios.','Cada tendência tem riscos próprios de engenharia e experiência.'))
];
const labs:Lab[]=[
lab('h7-lab1',X('Evaluate a modern technology proposal','Evalúa una propuesta tecnológica moderna','Avalie uma proposta tecnológica moderna'),X('Decide whether a trend improves a user task enough to justify its costs and risks.','Decide si una tendencia mejora la tarea lo suficiente para justificar costos y riesgos.','Decida se uma tendência melhora tarefa o bastante para justificar custo e risco.'),[
{title:X('Define users and task','Define usuarios y tarea','Defina usuários e tarefa'),expected:X('Describe the user group, task, setting, current alternative, and success measure.','Describe grupo, tarea, contexto, alternativa y medida de éxito.','Descreva grupo, tarefa, contexto, alternativa e medida de sucesso.')},{title:X('Gather evidence','Reúne evidencia','Reúna evidências'),expected:X('Use primary documentation, independent evaluations, and representative user feedback; separate claims from measured outcomes.','Usa documentación primaria, evaluaciones independientes y comentarios representativos; separa publicidad de resultados.','Use documentação primária, avaliações independentes e retorno representativo; separe alegações de resultados medidos.')},{title:X('Assess impacts and alternatives','Evalúa impacto y alternativas','Avalie impactos e alternativas'),expected:X('Compare security, privacy, cost, accessibility, reliability, and a simpler alternative; state a decision and conditions to revisit it.','Compara seguridad, privacidad, costo, accesibilidad y opción simple; define decisión y condiciones de revisión.','Compare segurança, privacidade, custo, acessibilidade, confiabilidade e alternativa simples; registre decisão e condições para revê-la.')}
]),lab('h7-lab2',X('Create a safeguards checklist','Crea una lista de salvaguardas','Crie lista de salvaguardas'),X('Apply risk review to an AI, cloud, blockchain, low-code, or immersive use case.','Aplica revisión de riesgos a un caso de IA, nube, blockchain, low-code o inmersivo.','Aplique análise de risco a caso de IA, nuvem, blockchain, low-code ou imersivo.'),[
{title:X('Select a use case','Elige un caso de uso','Escolha caso de uso'),expected:X('State the proposed capability, users, decisions affected, and data involved.','Indica capacidad, usuarios, decisiones y datos implicados.','Indique capacidade, usuários, decisões afetadas e dados envolvidos.')},{title:X('Identify failure and harm','Identifica fallos y daños','Identifique falhas e danos'),expected:X('List misuse, incorrect output, outage, privacy, bias, accessibility, or dependency risks relevant to the case.','Enumera riesgos pertinentes de mal uso, error, caída, privacidad, sesgo, acceso o dependencia.','Liste riscos relevantes de mau uso, erro, indisponibilidade, privacidade, viés, acesso ou dependência.')},{title:X('Assign controls and owners','Asigna controles y responsables','Atribua controles e responsáveis'),expected:X('Name a preventive check, monitoring signal, response owner, user notice, and rollback or exit path.','Define prevención, señal de monitoreo, responsable, aviso y reversión o salida.','Nomeie controle preventivo, sinal de monitoramento, responsável, aviso ao usuário e reversão ou saída.')}
])
];
